const item = $input.first().json;

const requiredFields = [
  'Diagnosis',
  'Physician Plan',
  'Physician Message',
  'Target Region',
  'Output Language',
];

const missingFields = requiredFields.filter((field) => {
  const value = item[field];
  return value === undefined || value === null || String(value).trim() === '';
});

if (missingFields.length > 0) {
  return [
    {
      json: {
        ...item,
        validation_passed: false,
        validation_error: `Missing required fields: ${missingFields.join(', ')}`,
      },
    },
  ];
}

return [
  {
    json: {
      ...item,
      validation_passed: true,
      validation_error: '',
    },
  },
];

const MAX_RESULTS = 5;
const RAW_RESULT_LIMIT = 10;

// Brave Searchのレスポンス
const input = $input.first().json;

// 患者説明ワークフローの入力情報
const context = $('Prepare Workflow Context').item.json;

// 最初から5件に限定せず、候補を少し広めに確認
const rawResults = (input.web?.results ?? []).slice(
  0,
  RAW_RESULT_LIMIT
);

// Brave Searchの検索情報
const query = input.query?.original ?? '';

const restrictedDomains =
  input.query?.search_operators?.sites ?? [];

// 明らかなノイズのみ除外
const excludedPatterns = [
  /guide to authors/i,
  /instructions for authors/i,
  /投稿規定/i,
  /学術委員会/i,
  /採用情報/i,
  /求人/i,
  /セミナー/i,
  /学会開催/i,
];

const normalizedResults = rawResults
  .map((result, index) => {
    const title = result.title ?? '';
    const description = result.description ?? '';
    const url = result.url ?? '';

    let hostname =
      result.meta_url?.hostname ??
      result.profile?.long_name ??
      '';

    hostname = String(hostname)
      .trim()
      .toLowerCase()
      .replace(/^www\./, '');

    const isPdf =
      result.content_type === 'pdf' ||
      /\.pdf(?:$|\?)/i.test(url);

    const excluded = excludedPatterns.some(
      (pattern) =>
        pattern.test(title) ||
        pattern.test(description) ||
        pattern.test(url)
    );

    return {
      original_rank: index + 1,
      title,
      url,
      description,
      hostname,
      language: result.language ?? '',
      content_type: isPdf ? 'pdf' : 'html',
      excluded,
      exclusion_reason: excluded
        ? 'Likely administrative, promotional, or non-clinical content'
        : '',
    };
  })
  .filter((result) => {
    const domainAllowed =
      restrictedDomains.length === 0 ||
      restrictedDomains.some((domain) => {
        const normalizedDomain = String(domain)
          .trim()
          .toLowerCase()
          .replace(/^www\./, '');

        return (
          result.hostname === normalizedDomain ||
          result.hostname.endsWith(
            `.${normalizedDomain}`
          )
        );
      });

    return domainAllowed && !result.excluded;
  })
  .slice(0, MAX_RESULTS)
  .map((result, index) => ({
    ...result,
    rank: index + 1,
  }));

return [
  {
    json: {
      // 医師が入力した情報を保持
      Diagnosis: context.Diagnosis,
      'Physician Plan': context['Physician Plan'],
      'Physician Message':
        context['Physician Message'],
      'Target Region': context['Target Region'],
      'Output Language':
        context['Output Language'],
      'Additional Notes':
        context['Additional Notes'] ?? '',
      Status: context.Status,
      row_number: context.row_number,
      'Search Purpose': context['Search Purpose'],

      // 検索結果
      search_query: query,
      restricted_domains: restrictedDomains,
      total_raw_results:
        input.web?.results?.length ?? 0,
      analyzed_result_count: rawResults.length,
      total_filtered_results:
        normalizedResults.length,
      search_results: normalizedResults,
    },
  },
];

const input = $input.first().json;

const candidates = input.search_results ?? [];

// 候補がない場合
if (candidates.length === 0) {
  return [
    {
      json: {
        ...input,
        evaluated_candidates: [],
        guideline_selection: {
          found: false,
          reason:
            "No usable guideline or patient education source was found.",
          selected_title: "",
          selected_url: "",
          publication_year: null,
          content_type: "",
          hostname: "",
          document_type: "",
          search_rank: null,
          selection_score: null,
          selection_reasons: [],
        },
      },
    },
  ];
}

/**
 * 候補ページを評価する
 *
 * 優先順位：
 * 1. 正式な診療ガイドライン
 * 2. 公的機関・専門学会の患者向け情報
 * 3. 大学病院・公的病院の患者向け情報
 * 4. その他の臨床情報
 * 5. 研究課題・研究成果データベース
 */
function evaluateCandidate(candidate) {
  const title = String(candidate.title ?? "");
  const description = String(candidate.description ?? "");
  const hostname = String(candidate.hostname ?? "")
    .trim()
    .toLowerCase()
    .replace(/^www\./, "");

  const combinedText = `${title} ${description}`;

  let score = 0;
  const reasons = [];

  /*
   * 文書タイプの事前判定
   */

  const looksLikeResearchRecord =
    /研究成果データベース|研究課題|研究班|研究計画|科学研究費|research project|research database/i.test(
      combinedText
    );

  const looksLikeFormalGuideline =
    /診療ガイドライン|治療ガイドライン|clinical practice guideline|guidelines? for/i.test(
      title
    ) && !looksLikeResearchRecord;

  const looksLikePatientEducation =
    /患者の皆様|患者さん|患者向け|一般の方|病気について|循環器病について知る|patient education|information for patients/i.test(
      combinedText
    );

  const containsClinicalGuidance =
    /推奨|診療指針|治療指針|治療方針|経過観察|recommendation|clinical guidance/i.test(
      combinedText
    );

  /*
   * 1. 情報源の信頼性
   */

  if (
    hostname.endsWith(".go.jp") ||
    hostname.includes(".go.jp")
  ) {
    score += 50;
    reasons.push(
      "Japanese government or public institution domain"
    );
  }

  if (
    hostname.endsWith(".ac.jp") ||
    hostname.includes(".ac.jp")
  ) {
    score += 35;
    reasons.push("Japanese academic institution domain");
  }

  if (
    hostname.endsWith(".or.jp") ||
    hostname.includes(".or.jp")
  ) {
    score += 25;
    reasons.push(
      "Japanese professional or nonprofit organization domain"
    );
  }

  /*
   * 2. 正式ガイドラインの可能性
   */

  if (looksLikeFormalGuideline) {
    score += 40;
    reasons.push("Likely formal clinical guideline");
  } else if (
    /ガイドライン|guideline/i.test(combinedText)
  ) {
    score += 10;
    reasons.push(
      "Guideline mentioned, but the document may not be the guideline itself"
    );
  }

  /*
   * 3. 患者説明への適性
   */

  if (looksLikePatientEducation) {
    score += 35;
    reasons.push(
      "Official or institutional patient education content"
    );
  }

  /*
   * 4. 臨床的な説明・指針を含む可能性
   */

  if (containsClinicalGuidance) {
    score += 15;
    reasons.push(
      "Contains clinical guidance or recommendation language"
    );
  }

  /*
   * 5. PDF文書
   */

  if (candidate.content_type === "pdf") {
    score += 10;
    reasons.push(
      "PDF document may contain formal guidance"
    );
  }

  /*
   * 6. 商用情報源
   */

  if (hostname === "clinicalsup.jp") {
    score -= 20;
    reasons.push("Commercial clinical information source");
  }

  /*
   * 7. 研究課題・研究成果データベース
   *
   * 「ガイドライン」という語が含まれていても、
   * 正式ガイドライン本文ではない可能性が高いため大幅に減点
   */

  if (looksLikeResearchRecord) {
    score -= 70;
    reasons.push(
      "Research project or research database record, not a current guideline or patient education document"
    );
  }

  /*
   * 検索スニペット内の年は、
   * 発行年・研究開始年・症例年などを区別できないため、
   * publication_yearとして自動採用しない
   */

  const publicationYear = null;

  return {
    ...candidate,
    publication_year: publicationYear,
    selection_score: score,
    selection_reasons: reasons,
    source_classification: {
      formal_guideline_candidate: looksLikeFormalGuideline,
      patient_education_candidate: looksLikePatientEducation,
      research_record: looksLikeResearchRecord,
      contains_clinical_guidance: containsClinicalGuidance,
    },
  };
}

// 全候補を評価し、点数順に並べる
const evaluatedCandidates = candidates
  .map(evaluateCandidate)
  .sort((a, b) => {
    if (b.selection_score !== a.selection_score) {
      return b.selection_score - a.selection_score;
    }

    // 同点の場合はBrave Searchの順位を優先
    return (a.rank ?? 999) - (b.rank ?? 999);
  });

const selectedSource = evaluatedCandidates[0];

/*
 * 選択した文書の種類を設定
 */

let documentType = "supporting_clinical_source";

if (
  selectedSource.source_classification
    ?.formal_guideline_candidate
) {
  documentType = "formal_guideline_candidate";
} else if (
  selectedSource.source_classification
    ?.patient_education_candidate
) {
  documentType =
    "official_patient_education_source";
} else if (
  selectedSource.source_classification
    ?.research_record
) {
  documentType = "research_record";
} else if (
  selectedSource.source_classification
    ?.contains_clinical_guidance
) {
  documentType = "clinical_guidance_source";
}

return [
  {
    json: {
      ...input,

      evaluated_candidates: evaluatedCandidates,

      guideline_selection: {
        found: true,
        reason:
          "Selected using source authority, formal guideline likelihood, patient education suitability, and document type.",
        selected_title: selectedSource.title ?? "",
        selected_url: selectedSource.url ?? "",
        publication_year:
          selectedSource.publication_year ?? null,
        content_type:
          selectedSource.content_type ?? "",
        hostname:
          selectedSource.hostname ?? "",
        document_type: documentType,
        search_rank:
          selectedSource.rank ?? null,
        selection_score:
          selectedSource.selection_score ?? null,
        selection_reasons:
          selectedSource.selection_reasons ?? [],
      },
    },
  },
];

const response = $input.first().json;

/*
 * 前段の選択結果を取得
 *
 * 実際のノード名と完全に一致させてください。
 */
const previous =
  $("Select Medical Source").first().json;

const html = String(response.data ?? "");

const statusCode =
  response.statusCode ??
  response.status_code ??
  null;

const responseHeaders =
  response.headers ?? {};

const responseContentType = String(
  responseHeaders["content-type"] ??
  responseHeaders["Content-Type"] ??
  ""
);

/*
 * HTMLエンティティをデコード
 */
function decodeHtml(text) {
  return String(text ?? "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&#160;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#34;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&apos;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">");
}

/*
 * HTMLから表示用テキストを生成
 */
function stripHtml(value) {
  return decodeHtml(
    String(value ?? "")
      .replace(
        /<script\b[^>]*>[\s\S]*?<\/script>/gi,
        " "
      )
      .replace(
        /<style\b[^>]*>[\s\S]*?<\/style>/gi,
        " "
      )
      .replace(
        /<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi,
        " "
      )
      .replace(
        /<svg\b[^>]*>[\s\S]*?<\/svg>/gi,
        " "
      )
      .replace(
        /<form\b[^>]*>[\s\S]*?<\/form>/gi,
        " "
      )
      .replace(/<!--[\s\S]*?-->/g, " ")
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<\/p>/gi, "\n")
      .replace(/<\/div>/gi, "\n")
      .replace(/<\/section>/gi, "\n")
      .replace(/<\/article>/gi, "\n")
      .replace(/<\/li>/gi, "\n")
      .replace(/<\/tr>/gi, "\n")
      .replace(/<\/h[1-6]>/gi, "\n")
      .replace(/<[^>]+>/g, " ")
  )
    .replace(/\r/g, "")
    .replace(/[ \t]+/g, " ")
    .replace(/ *\n */g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

/*
 * 正規表現の最初の一致を取得
 */
function firstMatch(pattern, source) {
  const match = String(source ?? "").match(pattern);

  if (!match?.[1]) {
    return "";
  }

  return stripHtml(match[1]);
}

/*
 * ページタイトル
 */
const pageTitle =
  firstMatch(
    /<title[^>]*>([\s\S]*?)<\/title>/i,
    html
  ) ||
  previous.guideline_selection?.selected_title ||
  "";

/*
 * meta description
 */
const metaDescription =
  firstMatch(
    /<meta[^>]+name=["']description["'][^>]+content=["']([\s\S]*?)["'][^>]*>/i,
    html
  ) ||
  firstMatch(
    /<meta[^>]+content=["']([\s\S]*?)["'][^>]+name=["']description["'][^>]*>/i,
    html
  ) ||
  "";

/*
 * ページ内の主要部分を優先して抽出
 *
 * article、main、bodyの順に試す
 */
const articleHtmlMatch = html.match(
  /<article\b[^>]*>([\s\S]*?)<\/article>/i
);

const mainHtmlMatch = html.match(
  /<main\b[^>]*>([\s\S]*?)<\/main>/i
);

const bodyHtmlMatch = html.match(
  /<body\b[^>]*>([\s\S]*?)<\/body>/i
);

const selectedContentHtml =
  articleHtmlMatch?.[1] ??
  mainHtmlMatch?.[1] ??
  bodyHtmlMatch?.[1] ??
  html;

/*
 * 可視テキスト
 */
const fullVisibleText = stripHtml(selectedContentHtml);

/*
 * 明らかなメニュー・共通表示を簡易除去
 *
 * 完全な本文抽出ではなく、
 * AIへ渡す前のノイズ削減を目的とする
 */
const boilerplatePatterns = [
  /^ホーム$/i,
  /^トップページ$/i,
  /^サイトマップ$/i,
  /^お問い合わせ$/i,
  /^プライバシーポリシー$/i,
  /^アクセシビリティ$/i,
  /^本文へ移動$/i,
  /^メニュー$/i,
  /^検索$/i,
  /^印刷$/i,
  /^ページの先頭へ$/i,
  /^Copyright\b/i,
  /^©\s*/i,
];

const cleanedLines = fullVisibleText
  .split("\n")
  .map((line) => line.trim())
  .filter(Boolean)
  .filter((line) => {
    return !boilerplatePatterns.some((pattern) =>
      pattern.test(line)
    );
  });

const cleanedText = cleanedLines
  .join("\n")
  .replace(/\n{3,}/g, "\n\n")
  .trim();

/*
 * 見出しを抽出
 */
const headingMatches = [
  ...selectedContentHtml.matchAll(
    /<h([1-6])[^>]*>([\s\S]*?)<\/h\1>/gi
  ),
];

const headings = headingMatches
  .map((match) => ({
    level: Number(match[1]),
    text: stripHtml(match[2]),
  }))
  .filter((item) => item.text);

/*
 * ページ内リンクを抽出
 */
const linkMatches = [
  ...html.matchAll(
    /<a[^>]+href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi
  ),
];

const baseUrl =
  previous.guideline_selection?.selected_url ?? "";

const links = linkMatches
  .map((match) => {
    const href = String(match[1] ?? "").trim();
    const text = stripHtml(match[2]);

    let absoluteUrl = href;

    try {
      absoluteUrl = new URL(
        href,
        baseUrl
      ).toString();
    } catch {
      absoluteUrl = href;
    }

    return {
      text,
      url: absoluteUrl,
    };
  })
  .filter((link) => {
    return (
      link.url &&
      !link.url.startsWith("javascript:") &&
      !link.url.startsWith("mailto:") &&
      !link.url.startsWith("tel:")
    );
  });

/*
 * PDFリンクを抽出
 */
const excludedPdfPatterns = [
  /errata/i,
  /正誤表/i,
  /coi/i,
  /利益相反/i,
  /転載/i,
  /permission/i,
  /申請書/i,
  /様式/i,
];

const pdfLinks = links.filter((link) => {
  const combined =
    `${link.text} ${link.url}`;

  const isPdf =
    /\.pdf(?:$|[?#])/i.test(link.url);

  const excluded =
    excludedPdfPatterns.some((pattern) =>
      pattern.test(combined)
    );

  return isPdf && !excluded;
});

/*
 * 重複リンクを除去
 */
const uniquePdfLinks = [
  ...new Map(
    pdfLinks.map((link) => [
      link.url,
      link,
    ])
  ).values(),
];

/*
 * AIへ渡す本文の文字数制限
 *
 * 長すぎるHTMLをそのままLLMへ渡すことを避ける
 */
const MAX_SOURCE_TEXT_LENGTH = 12000;

const sourceText =
  cleanedText.slice(
    0,
    MAX_SOURCE_TEXT_LENGTH
  );

const wasTruncated =
  cleanedText.length >
  MAX_SOURCE_TEXT_LENGTH;

/*
 * fetch成功判定
 *
 * Never ErrorがONのため、
 * 2xx以外でもノード自体は成功する可能性がある
 */
const fetchSuccess =
  statusCode !== null
    ? statusCode >= 200 &&
      statusCode < 300
    : html.length > 0;

/*
 * 本文として利用できる最低条件
 */
const minimumUsefulLength = 300;

const contentUsable =
  fetchSuccess &&
  sourceText.length >= minimumUsefulLength;

let accessStatus =
  "content_available";

if (!fetchSuccess) {
  accessStatus = "fetch_failed";
} else if (!contentUsable) {
  accessStatus =
    "insufficient_public_content";
} else if (wasTruncated) {
  accessStatus =
    "content_available_truncated";
}

/*
 * 出力
 */
return [
  {
    json: {
      ...previous,

      source_content: {
        fetch_success: fetchSuccess,
        content_usable: contentUsable,

        status_code: statusCode,
        response_content_type:
          responseContentType,

        source_url: baseUrl,
        page_title: pageTitle,
        meta_description:
          metaDescription,

        selected_source_type:
          previous.guideline_selection
            ?.document_type ?? "",

        organization_hostname:
          previous.guideline_selection
            ?.hostname ?? "",

        access_status: accessStatus,

        heading_count:
          headings.length,

        headings:
          headings.slice(0, 30),

        supporting_pdf_available:
          uniquePdfLinks.length > 0,

        supporting_pdf_links:
          uniquePdfLinks.slice(0, 10),

        source_text:
          sourceText,

        source_text_length:
          sourceText.length,

        original_text_length:
          cleanedText.length,

        text_truncated:
          wasTruncated,

        extraction_method:
          articleHtmlMatch
            ? "article"
            : mainHtmlMatch
              ? "main"
              : bodyHtmlMatch
                ? "body"
                : "full_html",
      },
    },
  },
];

const input = $input.first().json;
const report = String(input.text ?? "").trim();

if (!report) {
  throw new Error(
    "Generate Personalized Patient Education returned no text."
  );
}

const requiredHeadings = [
  "# Patient Education Report",
  "## Diagnosis",
  "## Your Doctor's Treatment Plan",
  "## A Message From Your Doctor",
  "## Understanding Your Condition",
  "## Why This Plan Was Recommended",
  "## What You Should Do",
  "## When You Should Seek Medical Attention",
  "## Questions for Your Next Visit",
  "## Information Source",
  "## Important Note",
];

const missingHeadings = requiredHeadings.filter(
  (heading) => !report.includes(heading)
);

if (missingHeadings.length > 0) {
  throw new Error(
    `Missing required headings: ${missingHeadings.join(", ")}`
  );
}

function extractSection(startHeading, endHeading = null) {
  const startIndex = report.indexOf(startHeading);

  if (startIndex === -1) {
    return "";
  }

  if (!endHeading) {
    return report.slice(startIndex).trim();
  }

  const endIndex = report.indexOf(
    endHeading,
    startIndex + startHeading.length
  );

  if (endIndex === -1) {
    return report.slice(startIndex).trim();
  }

  return report.slice(startIndex, endIndex).trim();
}

/*
==================================================
Page 1
==================================================
*/

const page1Sections = [
  extractSection(
    "# Patient Education Report",
    "## Diagnosis"
  ),

  extractSection(
    "## Diagnosis",
    "## Your Doctor's Treatment Plan"
  ),

  extractSection(
    "## Your Doctor's Treatment Plan",
    "## A Message From Your Doctor"
  ),

  extractSection(
    "## A Message From Your Doctor",
    "## Understanding Your Condition"
  ),

  extractSection(
    "## Understanding Your Condition",
    "## Why This Plan Was Recommended"
  ),
];

/*
==================================================
Page 2
==================================================
*/

const page2Sections = [
  extractSection(
    "## Why This Plan Was Recommended",
    "## What You Should Do"
  ),

  extractSection(
    "## What You Should Do",
    "## When You Should Seek Medical Attention"
  ),

  extractSection(
    "## When You Should Seek Medical Attention",
    "## Questions for Your Next Visit"
  ),

  extractSection(
    "## Questions for Your Next Visit",
    "## Information Source"
  ),

  extractSection(
    "## Information Source",
    "## Important Note"
  ),

  extractSection(
    "## Important Note"
  ),
];

function joinSections(sections) {
  return sections
    .filter(Boolean)
    .join("\n\n")
    .replace(/^##\s+/gm, "")
    .replace(/^#\s+/gm, "")
    .replace(/^\*\s+/gm, "• ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

/*
 * Google Docsでページ上部に約3行分の余白を作る
 * 4つの改行で、見た目として約3行分の空白になる想定
 */
const PAGE_TOP_MARGIN = "\n\n\n\n";

const page1 =
  PAGE_TOP_MARGIN +
  joinSections(page1Sections);

const page2 =
  PAGE_TOP_MARGIN +
  joinSections(page2Sections);

return [
  {
    json: {
      ...input,

      full_report: report,

      page1,

      page2,

      page_count: 2,

      split_success: true,
    },
  },
];
